        return {'status': 'error', 'points': 0}
    points = 0
    bonus = 0
    if spend >= 1000:
        bonus = 50
    if spend > 500:
        points = (spend - 500) // 10 * 2
    else:
        points = spend // 10
    return {'status': 'ok', 'points': points + bonus}

